"""Runtime support for modules generated by ``patchgen``.

This module is used by the ``_patches.py`` modules that ``scripts/patchgen``
generates for instrumentation packages. It is not a public API: generated
code and this module are versioned together.

It provides:

* the :data:`MISSING` sentinel and :data:`Missing` type used for parameters
  that only exist in some supported library versions,
* :class:`Manual`, the escape hatch for patches that are not a wrapper around
  a single callable,
* transactional apply/unwind of class-scope patches (:func:`apply_all`,
  :func:`unwind`) and per-object patches (:func:`apply_instance`,
  :func:`remove_instance`),
* rate-limited logging for bind failures and signature mismatches,
* strict mode (``OTEL_PYTHON_PATCH_STRICT=true``), which turns lock mismatches
  into exceptions. Intended for CI.

Frame depth: the wrapper built by :func:`bind_wrapper` adds
exactly :data:`WRAPPER_FRAMES` Python frames between the caller of the patched
target and the user's wrapper implementation (``wrapt``'s C
``FunctionWrapper.__call__`` adds none). For an ``async def`` implementation,
the one frame is the fail-open guard coroutine the caller awaits. Inside the
implementation, the original runs one frame below it: ``args.call()`` for a
sync target, or the recording coroutine that ``args.call()`` returns for a
coroutine target awaited in an ``async def`` implementation. Stack-walking code
(``logging``/``warnings`` ``stacklevel``, ``caller_package``-style helpers) can
rely on this; interpreters such as PyPy or debuggers may add frames of their own.
"""

from __future__ import annotations

import enum
import functools
import importlib
import inspect
import logging
import os
import sys
import threading
import time
import types
from collections.abc import Awaitable, Callable, Sequence
from dataclasses import dataclass, field
from typing import TYPE_CHECKING, Any, Final, Literal, TypeVar

import wrapt
from packaging.specifiers import SpecifierSet
from packaging.version import InvalidVersion, Version

from opentelemetry.instrumentation.environment_variables import (
    OTEL_PYTHON_PATCH_STRICT,
)
from opentelemetry.util._importlib_metadata import PackageNotFoundError, version

_logger = logging.getLogger(__name__)

# wrapt 1.x ships no type information and wrapt 2.x types FunctionWrapper as a
# generic; an explicit ``Any`` alias type-checks the same way under both.
_FunctionWrapper: Any = getattr(wrapt, "FunctionWrapper")  # noqa: B009

__all__ = [
    "MISSING",
    "WRAPPER_FRAMES",
    "BoundArgs",
    "InstancePatchDef",
    "Manual",
    "Missing",
    "PatchDef",
    "PatchMismatchError",
    "Registry",
    "apply_all",
    "apply_instance",
    "bind_wrapper",
    "log_bind_failure",
    "log_signature_mismatch",
    "remove_instance",
    "replace_raw_args",
    "strict_mode",
    "unwind",
    "var_keyword_name",
    "var_positional_name",
]


class _MissingType(enum.Enum):
    MISSING = "MISSING"

    def __repr__(self) -> str:
        return "MISSING"


MISSING: Final = _MissingType.MISSING
"""Value of an ``Args`` field whose parameter does not exist in the installed version."""

Missing = Literal[_MissingType.MISSING]
"""Type of :data:`MISSING`; generated fields are typed ``T | Missing``."""

WRAPPER_FRAMES: Final = 1
"""Python frames :func:`bind_wrapper` adds between the patched target's caller and the impl."""

WraptWrapper = Callable[[Callable[..., Any], Any, tuple[Any, ...], dict[str, Any]], Any]
"""A ``wrapt``-style wrapper ``(wrapped, instance, args, kwargs) -> result``."""

WrapperFactory = Callable[[inspect.Signature], WraptWrapper]
"""Builds the per-call wrapper given the installed signature (without ``self``)."""

ParamShape = tuple[tuple[str, str, bool], ...]
"""``(name, kind, has_default)`` per parameter, used to compare installed signatures with the lock."""

RATE_LIMIT_SECONDS: Final = 300.0

_RESERVED_ATTRS: Final = frozenset(
    {
        "raw_args",
        "raw_kwargs",
        "_wrapped",
        "_sig",
        "_replace_plan",
        "_call_state",
        "_call_result",
        "_in_guard",
        "_pending",
        "_original_raised",
        "_library",
        "_patch_name",
        "_detach",
        "var_args",
        "var_kwargs",
        "call",
    }
)

_POSITIONAL_KINDS: Final = (
    inspect.Parameter.POSITIONAL_ONLY,
    inspect.Parameter.POSITIONAL_OR_KEYWORD,
)

# ``BoundArgs._call_state`` values: how far the latest ``args.call()`` got with the original.
_NOT_ENTERED: Final = 0
"""``args.call()`` has not invoked the original (falsy on purpose: checked on the hot path)."""
_ENTERED: Final = 1
"""The original was invoked and has not returned (or raised, or its coroutine is still pending)."""
_RETURNED: Final = 2
"""The original returned; its result is in ``BoundArgs._call_result``."""


class PatchMismatchError(RuntimeError):
    """Raised in strict mode when the installed library does not match the lock."""


def strict_mode() -> bool:
    """Whether ``OTEL_PYTHON_PATCH_STRICT`` is set to ``true``."""
    return os.environ.get(OTEL_PYTHON_PATCH_STRICT, "").strip().lower() == "true"


@dataclass(frozen=True)
class Manual:
    """A hand-written patch registered alongside generated ones.

    ``apply`` and ``remove`` are called by :func:`apply_all` / :func:`unwind`
    in registration order (and reverse order respectively). Manual patches are
    excluded from signature checking.
    """

    apply: Callable[[], None]
    remove: Callable[[], None]


@dataclass(frozen=True)
class PatchDef:
    """Class-scope patch description emitted by generated code.

    ``versions`` is an optional PEP 440 specifier; the patch is only applied
    when the installed library version is in that range.
    """

    name: str
    target: str
    required: bool
    method: bool
    locked_shapes: frozenset[ParamShape]
    make_wrapper: WrapperFactory
    versions: str | None = None


@dataclass(frozen=True)
class InstancePatchDef:
    """Instance-scope patch description emitted by generated code."""

    name: str
    attr: str
    locked_shapes: frozenset[ParamShape]
    make_wrapper: WrapperFactory
    versions: str | None = None


class BoundArgs:
    """Base class for generated ``*Args`` call-argument views.

    Instances store only the raw call tuple/dict and the wrapped callable.
    Per-parameter descriptors and the binding signature are attached by
    :func:`bind_wrapper` at ``instrument()`` time so arguments are resolved
    lazily on attribute access without calling :meth:`inspect.Signature.bind`.
    """

    __slots__ = (
        "_call_result",
        "_call_state",
        "_in_guard",
        "_original_raised",
        "_pending",
        "_wrapped",
        "raw_args",
        "raw_kwargs",
    )

    raw_args: tuple[Any, ...]
    raw_kwargs: dict[str, Any]
    _wrapped: Callable[..., Any]
    _call_state: int
    """One of ``_NOT_ENTERED``, ``_ENTERED`` or ``_RETURNED``, for the latest ``args.call()``."""
    _call_result: Any
    """The original's result; only set once ``_call_state`` is ``_RETURNED``."""
    _in_guard: bool
    """Whether the wrapper runs inside ``_guard_coroutine`` (an async wrapper)."""
    _pending: int
    """Inside a guard: originals started by ``args.call()`` whose completion hasn't been seen."""
    _original_raised: bool
    """Inside a guard: whether any original raised (sticky across retries and concurrent calls)."""
    _sig: inspect.Signature | None = None
    _replace_plan: _ReplacePlan | None = None
    _library: str = "<unknown>"
    _patch_name: str = "call"
    _detach: Callable[[], None] | None = None

    def __init__(
        self,
        raw_args: tuple[Any, ...],
        raw_kwargs: dict[str, Any],
        _wrapped: Callable[..., Any],
    ) -> None:
        self.raw_args = raw_args
        self.raw_kwargs = raw_kwargs
        self._wrapped = _wrapped
        self._call_state = _NOT_ENTERED
        self._in_guard = False

    def __repr__(self) -> str:
        return f"{type(self).__name__}(raw_args={self.raw_args!r}, raw_kwargs={self.raw_kwargs!r})"

    if not TYPE_CHECKING:

        def call(self, /, **updates: Any) -> Any:
            """Invoke the wrapped target once, replacing any parameters passed here.

            Records how far the original got in ``_call_state`` (and its result
            in ``_call_result``) so the dispatcher can tell a wrapper failure
            before, during and after the original apart. The original always
            runs directly in this frame (see :data:`WRAPPER_FRAMES`).
            """
            try:
                if not updates:
                    self._call_state = _ENTERED
                    result = self._wrapped(*self.raw_args, **self.raw_kwargs)
                else:
                    args = self.raw_args
                    kwargs = self.raw_kwargs
                    replaced = False
                    for val in updates.values():
                        if val is MISSING:
                            updates = {k: v for k, v in updates.items() if v is not MISSING}
                            break
                    if updates:
                        try:
                            args, kwargs = _replaced_raw_args(self, updates)
                            replaced = True
                        except (KeyError, TypeError):
                            log_bind_failure(self._library, self._patch_name)
                            if self._detach is not None:
                                self._detach()
                    self._call_state = _ENTERED
                    if not replaced:
                        result = self._wrapped(*args, **kwargs)
                    else:
                        try:
                            result = self._wrapped(*args, **kwargs)
                        except TypeError as exc:
                            if _in_traceback(exc.__traceback__, self._wrapped):
                                raise
                            log_bind_failure(self._library, self._patch_name)
                            if self._detach is not None:
                                self._detach()
                            result = self._wrapped(*self.raw_args, **self.raw_kwargs)
            except BaseException:
                if self._in_guard:
                    # A sync original (or one that raised while creating its
                    # coroutine) raised: later wrapper failures must propagate.
                    self._original_raised = True
                raise
            if self._in_guard:
                # Every call inside an async wrapper, retries included.
                return _guarded_result(self, result)
            self._call_state = _RETURNED
            self._call_result = result
            return result


def _guarded_result(bound: BoundArgs, result: Any) -> Any:
    """Record the original's outcome for ``args.call()`` inside an async wrapper.

    Several calls may be in flight at once (``asyncio.gather``), so the guard
    only fails open after the original returned when no original is pending
    and none raised.
    """
    if inspect.iscoroutine(result):
        # The original has only returned once its coroutine finishes; record that when it does.
        bound._pending += 1
        return _await_original(bound, result)
    if inspect.isawaitable(result):
        # E.g. an awaitable context manager: when the original's work completes is
        # unknown, so count it as pending for good and let later wrapper failures propagate.
        bound._pending += 1
        return result
    bound._call_state = _RETURNED
    bound._call_result = result
    return result


def _replaced_raw_args(bound: BoundArgs, updates: dict[str, Any]) -> tuple[tuple[Any, ...], dict[str, Any]]:
    """Apply ``updates`` for :meth:`BoundArgs.call`; raises ``KeyError`` / ``TypeError`` on failure."""
    plan = bound._replace_plan
    if plan is not None and replace_raw_args is _replace_raw_args_public:
        return _apply_replace_plan(plan, bound.raw_args, bound.raw_kwargs, updates)
    sig = bound._sig if bound._sig is not None else _installed_signature(bound._wrapped)
    if replace_raw_args is not _replace_raw_args_public:
        # Honour a monkeypatched module-level ``replace_raw_args`` (used by tests).
        return replace_raw_args(sig, bound.raw_args, bound.raw_kwargs, updates)
    return _replace_raw_args(sig, bound.raw_args, bound.raw_kwargs, updates)


async def _await_original(bound: BoundArgs, coro: Awaitable[Any]) -> Any:
    """Await the original's coroutine for ``args.call()`` and record how it finished."""
    try:
        result = await coro
    except BaseException:
        bound._pending -= 1
        bound._original_raised = True
        raise
    bound._pending -= 1
    bound._call_state = _RETURNED
    bound._call_result = result
    return result


async def _guard_coroutine(bound: BoundArgs, coro: Awaitable[Any]) -> Any:
    """Await an async wrapper's coroutine with the same fail-open rules as the sync dispatcher.

    The wrapper body only runs here, after the dispatcher has returned, so
    the dispatcher's own ``try`` cannot see its exceptions.
    """
    try:
        return await coro
    except Exception as exc:  # pylint: disable=broad-exception-caught
        state = bound._call_state
        if state == _RETURNED and not bound._pending and not bound._original_raised:
            if strict_mode():
                raise
            return _fail_open_after_return(bound)
        if state != _NOT_ENTERED or _in_traceback(exc.__traceback__, bound._wrapped):
            raise
        log_bind_failure(bound._library, bound._patch_name)
        if bound._detach is not None:
            bound._detach()
    result = bound._wrapped(*bound.raw_args, **bound.raw_kwargs)
    if inspect.isawaitable(result):
        return await result
    return result


def _fail_open_after_return(bound: BoundArgs) -> Any:
    """Log (and detach) after a wrapper raised once the original returned; return its result.

    Callers re-raise instead in strict mode, so test suites still see wrapper bugs.
    """
    detach = bound._detach
    _log_wrapper_failure(bound._library, bound._patch_name, detaching=detach is not None)
    if detach is not None:
        detach()
    return bound._call_result


class _ParamGetter:
    """Descriptor that resolves a single parameter lazily from ``raw_args`` / ``raw_kwargs``."""

    __slots__ = ("can_kw", "default", "idx", "name")

    def __init__(self, idx: int | None, name: str, can_kw: bool, default: Any) -> None:
        self.idx = idx
        self.name = name
        self.can_kw = can_kw
        self.default = default

    def __get__(self, obj: BoundArgs | None, owner: type | None = None) -> Any:
        if obj is None:
            return self
        if self.idx is not None and self.idx < len(obj.raw_args):
            return obj.raw_args[self.idx]
        if self.can_kw and self.name in obj.raw_kwargs:
            return obj.raw_kwargs[self.name]
        if self.default is inspect.Parameter.empty:
            raise TypeError(f"missing a required argument: {self.name!r}")
        return self.default


class _VarArgsGetter:
    """Descriptor that slices ``*args`` from ``raw_args`` after leading positional parameters."""

    __slots__ = ("start",)

    def __init__(self, start: int) -> None:
        self.start = start

    def __get__(self, obj: BoundArgs | None, owner: type | None = None) -> Any:
        if obj is None:
            return self
        return obj.raw_args[self.start :]


class _VarKwargsGetter:
    """Descriptor that extracts ``**kwargs`` entries not bound to named parameters."""

    __slots__ = ("named_kw",)

    def __init__(self, named_kw: frozenset[str] | None) -> None:
        self.named_kw = named_kw

    def __get__(self, obj: BoundArgs | None, owner: type | None = None) -> Any:
        if obj is None:
            return self
        if self.named_kw is None or not obj.raw_kwargs:
            return {}
        if not self.named_kw:
            return dict(obj.raw_kwargs)
        return {k: v for k, v in obj.raw_kwargs.items() if k not in self.named_kw}


def _in_traceback(tb: types.TracebackType | None, target: Any, *, no_code: bool = True) -> bool:
    if tb is None:
        return False
    codes: set[types.CodeType] = set()
    seen: set[int] = set()
    cur: Any = target
    for _ in range(32):
        if cur is None or id(cur) in seen:
            break
        seen.add(id(cur))
        if isinstance(cur, types.FunctionType):
            codes.add(cur.__code__)
        elif isinstance(cur, types.MethodType):
            if isinstance(cur.__func__, types.FunctionType):
                codes.add(cur.__func__.__code__)
        elif callable(cur) and not isinstance(cur, types.BuiltinFunctionType):
            call_attr = inspect.getattr_static(type(cur), "__call__", None)
            if isinstance(call_attr, types.FunctionType):
                codes.add(call_attr.__code__)
            elif isinstance(call_attr, types.MethodType) and isinstance(call_attr.__func__, types.FunctionType):
                codes.add(call_attr.__func__.__code__)
            exec_attr = inspect.getattr_static(type(cur), "_execute_mock_call", None)
            if isinstance(exec_attr, types.FunctionType):
                codes.add(exec_attr.__code__)
        if isinstance(cur, functools.partial):
            cur = cur.func
        elif isinstance(cur, types.MethodType):
            cur = (
                inspect.getattr_static(cur, "__wrapped__", None)
                or inspect.getattr_static(cur.__func__, "__wrapped__", None)
                or cur.__func__
            )
        else:
            cur = inspect.getattr_static(cur, "__wrapped__", None)
    if not codes:
        return no_code
    while tb is not None:
        if tb.tb_frame.f_code in codes:
            return True
        tb = tb.tb_next
    return False


def _record_bind_mismatch(
    library: str,
    patch_name: str,
    sig: inspect.Signature,
    args: tuple[Any, ...],
    kwargs: dict[str, Any],
    detach: Callable[[], None] | None,
) -> None:
    try:
        sig.bind(*args, **kwargs)
        raise TypeError("missing required patch field")
    except Exception:  # pylint: disable=broad-exception-caught
        log_bind_failure(library, patch_name)
    if detach is not None:
        detach()


def _fail_bind(
    library: str,
    patch_name: str,
    sig: inspect.Signature,
    wrapped: Callable[..., Any],
    args: tuple[Any, ...],
    kwargs: dict[str, Any],
    detach: Callable[[], None] | None = None,
    *,
    missing_required: bool = False,
) -> Any:
    if missing_required:
        _record_bind_mismatch(library, patch_name, sig, args, kwargs, detach)
        return wrapped(*args, **kwargs)
    try:
        result = wrapped(*args, **kwargs)
    except TypeError as exc:
        if _in_traceback(exc.__traceback__, wrapped, no_code=False):
            _record_bind_mismatch(library, patch_name, sig, args, kwargs, detach)
        raise
    except Exception:
        _record_bind_mismatch(library, patch_name, sig, args, kwargs, detach)
        raise
    _record_bind_mismatch(library, patch_name, sig, args, kwargs, detach)
    return result


def bind_wrapper(
    library: str,
    patch_name: str,
    args_cls: type[BoundArgs],
    impl: Callable[[Any, Any, Any], Any],
) -> WrapperFactory:
    """Build a :data:`WrapperFactory` that binds call arguments into ``args_cls``.

    Attaches per-parameter descriptors to a subclass of ``args_cls`` once at
    ``instrument()`` time so per-call binding only stores ``(args, kwargs,
    wrapped)`` and resolves parameters lazily on attribute access.
    """
    annotations: dict[str, Any] = getattr(args_cls, "__annotations__", {})
    required_params = tuple(
        name for name in annotations if name not in _RESERVED_ATTRS and getattr(args_cls, name, None) is not MISSING
    )
    req_var_args = "var_args" in annotations and getattr(args_cls, "var_args", None) is not MISSING
    req_var_kwargs = "var_kwargs" in annotations and getattr(args_cls, "var_kwargs", None) is not MISSING
    # Only an ``async def`` wrapper returns a coroutine of its own body, which the
    # dispatcher must guard (its exceptions surface after the dispatcher returned).
    async_impl = inspect.iscoroutinefunction(impl)

    def factory(sig: inspect.Signature) -> WraptWrapper:
        pos_params: list[inspect.Parameter] = []
        kw_only_params: list[inspect.Parameter] = []
        has_var_pos = False
        has_var_kw = False
        for param in sig.parameters.values():
            if param.kind in _POSITIONAL_KINDS:
                pos_params.append(param)
            elif param.kind is inspect.Parameter.VAR_POSITIONAL:
                has_var_pos = True
            elif param.kind is inspect.Parameter.KEYWORD_ONLY:
                kw_only_params.append(param)
            elif param.kind is inspect.Parameter.VAR_KEYWORD:
                has_var_kw = True

        sig_named = {p.name for p in pos_params} | {p.name for p in kw_only_params}
        missing_required = any(name not in sig_named for name in required_params)
        named_kw = frozenset(
            p.name for p in pos_params if p.kind is inspect.Parameter.POSITIONAL_OR_KEYWORD
        ) | frozenset(p.name for p in kw_only_params)

        namespace: dict[str, Any] = {
            "__slots__": (),
            "__module__": args_cls.__module__,
            "__qualname__": args_cls.__qualname__,
            "_sig": sig,
            "_replace_plan": _ReplacePlan(sig),
            "_library": library,
            "_patch_name": patch_name,
            "_detach": None,
        }
        for idx, param in enumerate(pos_params):
            if param.name in _RESERVED_ATTRS:
                continue
            can_kw = param.kind is inspect.Parameter.POSITIONAL_OR_KEYWORD
            namespace[param.name] = _ParamGetter(idx, param.name, can_kw, param.default)
        for param in kw_only_params:
            if param.name in _RESERVED_ATTRS:
                continue
            namespace[param.name] = _ParamGetter(None, param.name, True, param.default)
        if has_var_pos:
            namespace["var_args"] = _VarArgsGetter(len(pos_params))
        elif req_var_args:
            namespace["var_args"] = ()
        if has_var_kw:
            namespace["var_kwargs"] = _VarKwargsGetter(named_kw)
        elif req_var_kwargs:
            namespace["var_kwargs"] = _VarKwargsGetter(None)

        bound_cls: Any = type(args_cls.__name__, (args_cls,), namespace)

        n_pos = len(pos_params)
        max_pos = sys.maxsize if has_var_pos else n_pos
        min_pos_only = sum(
            1
            for p in pos_params
            if p.kind is inspect.Parameter.POSITIONAL_ONLY and p.default is inspect.Parameter.empty
        )
        min_pos_all = sum(1 for p in pos_params if p.default is inspect.Parameter.empty)
        req_kw_only = frozenset(p.name for p in kw_only_params if p.default is inspect.Parameter.empty)
        min_pos_no_kw = sys.maxsize if (req_kw_only or missing_required) else min_pos_all
        min_pos_with_kw = sys.maxsize if missing_required else min_pos_only
        bound_pos_kw_sets = tuple(
            frozenset(p.name for p in pos_params[:k] if p.kind is inspect.Parameter.POSITIONAL_OR_KEYWORD)
            for k in range(n_pos + 1)
        )
        valid_kw_by_nargs = tuple(named_kw - bound_pos_kw_sets[k] for k in range(n_pos + 1))
        req_kw_by_nargs = tuple(
            frozenset(p.name for p in pos_params[max(k, min_pos_only) : min_pos_all]) | req_kw_only
            for k in range(n_pos + 1)
        )

        def wrapper(
            wrapped: Callable[..., Any],
            instance: Any,
            args: tuple[Any, ...],
            kwargs: dict[str, Any],
        ) -> Any:
            n_args = len(args)
            if not kwargs:
                if not (min_pos_no_kw <= n_args <= max_pos):
                    return _fail_bind(
                        library,
                        patch_name,
                        sig,
                        wrapped,
                        args,
                        kwargs,
                        bound_cls._detach,
                        missing_required=missing_required,
                    )
            else:
                k = min(n_pos, n_args)
                req_kw = req_kw_by_nargs[k]
                if not (
                    min_pos_with_kw <= n_args <= max_pos
                    and (
                        bound_pos_kw_sets[k].isdisjoint(kwargs)
                        if has_var_kw
                        else valid_kw_by_nargs[k].issuperset(kwargs)
                    )
                    and (not req_kw or req_kw.issubset(kwargs))
                ):
                    return _fail_bind(
                        library,
                        patch_name,
                        sig,
                        wrapped,
                        args,
                        kwargs,
                        bound_cls._detach,
                        missing_required=missing_required,
                    )
            bound = bound_cls(args, kwargs, wrapped)
            try:
                result = impl(wrapped, instance, bound)
            except Exception as exc:  # pylint: disable=broad-exception-caught
                state = bound._call_state
                if state == _RETURNED:
                    # The wrapper failed after the original returned: hand back
                    # the original's result instead of the telemetry error.
                    if strict_mode():
                        raise
                    return _fail_open_after_return(bound)
                if state == _ENTERED or _in_traceback(exc.__traceback__, wrapped):
                    raise
                log_bind_failure(library, patch_name)
                if bound_cls._detach is not None:
                    bound_cls._detach()
                return wrapped(*args, **kwargs)
            if async_impl and not bound._call_state and inspect.iscoroutine(result):
                # An ``async def`` wrapper whose body hasn't run yet: guard it
                # so failures before the original fail open. Coroutines from
                # sync wrappers are not guarded: they may be the original's own
                # coroutine (``return wrapped(...)``), and cannot be told apart.
                bound._in_guard = True
                bound._pending = 0
                bound._original_raised = False
                return _guard_coroutine(bound, result)
            return result

        def set_detach(detach: Callable[[], None]) -> None:
            bound_cls._detach = staticmethod(detach)

        setattr(wrapper, "_set_detach", set_detach)
        return wrapper

    return factory


@dataclass
class _Applied:
    owner: Any = None
    attr: str = ""
    had_own: bool = False
    previous: Any = None
    installed: Any = None
    manual: Manual | None = None


def _still_installed(entry: _Applied) -> bool:
    """Whether the owner still holds the wrapper recorded in ``entry``.

    Compares the owner's own ``__dict__`` entry rather than ``getattr`` so that
    descriptors (our wrapper binds on attribute access) don't defeat the check.
    """
    if entry.installed is None:
        return False
    owner: object = entry.owner
    try:
        own = vars(owner)
    except TypeError:
        return False
    current: object = own.get(entry.attr)
    return current is entry.installed


@dataclass
class Registry:
    """Records what a generated module applied so it can be unwound.

    ``stdlib`` marks modules generated from a ``stdlib: true`` spec: the lock
    is keyed by Python ``major.minor`` and compared with the running
    interpreter rather than with an installed distribution.
    """

    library: str
    stdlib: bool = False
    _applied: list[_Applied] = field(default_factory=list[_Applied])

    @property
    def active(self) -> bool:
        """Whether a :class:`Manual` or one of the installed wrappers is still in place.

        A registry whose wrappers were all replaced by someone else (e.g.
        ``mock.patch``) is not active, so a later :func:`apply_all` applies again.
        """
        return any(entry.manual is not None or _still_installed(entry) for entry in self._applied)

    @property
    def subject(self) -> str:
        """What the lock's version numbers refer to, for log messages."""
        return "python" if self.stdlib else self.library

    def installed_version(self) -> str | None:
        """The version to compare with the lock: the distribution's, or Python's."""
        if self.stdlib:
            return f"{sys.version_info.major}.{sys.version_info.minor}"
        return _installed_version(self.library)

    def owns(self, obj: object) -> bool:
        """Whether ``obj`` is a class-level wrapper installed through this registry."""
        return any(entry.installed is obj for entry in self._applied if entry.manual is None)


class _InstancePatch(_FunctionWrapper):  # pylint: disable=abstract-method
    """Marker type for wrappers shadowing a method on a single object."""


class _InstanceOptOut(_FunctionWrapper):  # pylint: disable=abstract-method
    """Marker type that pins an object to the original method while the class is patched."""


def _passthrough(
    wrapped: Callable[..., Any],
    instance: Any,
    args: tuple[Any, ...],
    kwargs: dict[str, Any],
) -> Any:
    return wrapped(*args, **kwargs)


class _RateLimiter:
    def __init__(self, interval: float) -> None:
        self._interval = interval
        self._lock = threading.Lock()
        self._last: dict[tuple[str, ...], float] = {}

    def check(self, key: tuple[str, ...]) -> tuple[bool, bool]:
        """Return ``(should_log, first_time)`` for ``key``."""
        now = time.monotonic()
        with self._lock:
            last = self._last.get(key)
            if last is None:
                self._last[key] = now
                return True, True
            if now - last >= self._interval:
                self._last[key] = now
                return True, False
            return False, False

    def reset(self) -> None:
        with self._lock:
            self._last.clear()


_limiter = _RateLimiter(RATE_LIMIT_SECONDS)


def log_bind_failure(library: str, patch: str, *, exc_info: bool = True) -> None:
    """Log that call arguments could not be bound; rate limited per site.

    The first occurrence is logged at ``WARNING`` with the traceback, later
    ones at most once per :data:`RATE_LIMIT_SECONDS` without it.
    """
    should_log, first = _limiter.check(("bind", library, patch))
    if not should_log:
        return
    if first:
        _logger.warning(
            "%s: could not bind arguments for patch %r; calling the original without instrumentation",
            library,
            patch,
            exc_info=exc_info,
        )
    else:
        _logger.warning("%s: could not bind arguments for patch %r (repeated)", library, patch)


def _log_wrapper_failure(library: str, patch: str, *, detaching: bool) -> None:
    """Log that a wrapper raised after the original returned; rate limited per site."""
    should_log, first = _limiter.check(("after", library, patch))
    if not should_log:
        return
    if first:
        _logger.warning(
            "%s: wrapper for patch %r raised after the original returned; returning the original's result%s",
            library,
            patch,
            " and removing the patch" if detaching else "",
            exc_info=True,
        )
    else:
        _logger.warning("%s: wrapper for patch %r raised after the original returned (repeated)", library, patch)


def log_signature_mismatch(library: str, message: str) -> None:
    """Warn (rate limited) about a lock mismatch, or raise in strict mode."""
    if strict_mode():
        raise PatchMismatchError(f"{library}: {message}")
    should_log, _ = _limiter.check(("mismatch", library, message))
    if should_log:
        _logger.warning("%s: %s", library, message)


def _report_error(library: str, message: str) -> None:
    if strict_mode():
        raise PatchMismatchError(f"{library}: {message}")
    _logger.error("%s: %s", library, message)


def _resolve(target: str) -> tuple[Any, str, Any] | None:
    module_name, _, qualname = target.partition(":")
    parts = qualname.split(".")
    try:
        owner: Any = importlib.import_module(module_name)
        for part in parts[:-1]:
            owner = getattr(owner, part)
        raw: Any = inspect.getattr_static(owner, parts[-1], None)
        original: Any = raw if type(raw) in (classmethod, staticmethod) else getattr(owner, parts[-1])
    except Exception:  # pylint: disable=broad-exception-caught
        return None
    return owner, parts[-1], original


def _shape(sig: inspect.Signature) -> ParamShape:
    return tuple(
        (param.name, param.kind.name, param.default is not inspect.Parameter.empty) for param in sig.parameters.values()
    )


def _drop_first(sig: inspect.Signature) -> inspect.Signature:
    params = list(sig.parameters.values())
    return sig.replace(parameters=params[1:])


def var_positional_name(sig: inspect.Signature) -> str | None:
    """Name of the ``*args`` parameter of ``sig``, if any."""
    for param in sig.parameters.values():
        if param.kind is inspect.Parameter.VAR_POSITIONAL:
            return param.name
    return None


def var_keyword_name(sig: inspect.Signature) -> str | None:
    """Name of the ``**kwargs`` parameter of ``sig``, if any."""
    for param in sig.parameters.values():
        if param.kind is inspect.Parameter.VAR_KEYWORD:
            return param.name
    return None


_VAR_ARGS_KEY: Final = "var_args"
"""Reserved :func:`replace_raw_args` key that replaces the ``*args`` values."""


class _ReplacePlan:
    """Per-signature tables for :func:`_apply_replace_plan`.

    Built once per target at ``instrument()`` time (stored on the bound
    ``*Args`` class as ``_replace_plan``) so ``args.call(**updates)`` doesn't
    walk ``sig.parameters`` on every call.
    """

    __slots__ = ("has_var_kw", "keyword_ok", "leading", "positional", "positional_only", "var_args_name")

    def __init__(self, sig: inspect.Signature) -> None:
        # A Signature orders its parameters by kind, so positional ones come first.
        leading: list[inspect.Parameter] = []
        positional_only: set[str] = set()
        keyword_ok: set[str] = set()
        has_var_kw = False
        var_args_name: str | None = None
        for param in sig.parameters.values():
            kind = param.kind
            if kind is inspect.Parameter.POSITIONAL_OR_KEYWORD:
                leading.append(param)
                keyword_ok.add(param.name)
            elif kind is inspect.Parameter.POSITIONAL_ONLY:
                leading.append(param)
                positional_only.add(param.name)
            elif kind is inspect.Parameter.KEYWORD_ONLY:
                keyword_ok.add(param.name)
            elif kind is inspect.Parameter.VAR_POSITIONAL:
                var_args_name = param.name
            else:
                has_var_kw = True
        self.leading: tuple[inspect.Parameter, ...] = tuple(leading)
        self.positional: dict[str, int] = {param.name: idx for idx, param in enumerate(leading)}
        self.positional_only: frozenset[str] = frozenset(positional_only)
        self.keyword_ok: frozenset[str] = frozenset(keyword_ok)
        self.has_var_kw: bool = has_var_kw
        self.var_args_name: str | None = var_args_name


def _replace_raw_args(
    sig: inspect.Signature | None,
    raw_args: tuple[Any, ...],
    raw_kwargs: dict[str, Any],
    updates: dict[str, Any],
) -> tuple[tuple[Any, ...], dict[str, Any]]:
    return _apply_replace_plan(None if sig is None else _ReplacePlan(sig), raw_args, raw_kwargs, updates)


def _apply_replace_plan(
    plan: _ReplacePlan | None,
    raw_args: tuple[Any, ...],
    raw_kwargs: dict[str, Any],
    updates: dict[str, Any],
) -> tuple[tuple[Any, ...], dict[str, Any]]:
    args_list = list(raw_args)
    kwargs_copy = dict(raw_kwargs)
    if plan is None:
        if _VAR_ARGS_KEY in updates:
            raise KeyError(f"cannot replace {_VAR_ARGS_KEY!r} without a signature")
        kwargs_copy.update(updates)
        return tuple(args_list), kwargs_copy

    leading = plan.leading
    positional = plan.positional
    positional_only = plan.positional_only
    var_args_name = plan.var_args_name

    new_var_args: Sequence[Any] | None = None
    for name, value in updates.items():
        if name in (_VAR_ARGS_KEY, var_args_name):
            if var_args_name is None:
                raise KeyError(f"unknown parameter {name!r}: the signature has no *args")
            new_var_args = value
            continue
        idx = positional.get(name)
        if idx is not None and idx < len(args_list):
            if name in kwargs_copy and name not in positional_only:
                raise TypeError(f"multiple values for argument {name!r}")
            args_list[idx] = value
        elif idx is not None and name in positional_only:
            for preceding in leading[len(args_list) : idx]:
                if preceding.name in updates:
                    args_list.append(updates[preceding.name])
                elif preceding.default is not inspect.Parameter.empty and preceding.default is not MISSING:
                    args_list.append(preceding.default)
                else:
                    raise TypeError(
                        f"cannot replace positional-only parameter {name!r}: "
                        f"preceding parameter {preceding.name!r} was not passed"
                    )
            args_list.append(value)
        elif name in kwargs_copy or name in plan.keyword_ok or plan.has_var_kw:
            kwargs_copy[name] = value
        else:
            raise KeyError(f"unknown parameter {name!r}")

    if new_var_args is not None:
        # Positional parameters before *args; all of them must be passed positionally.
        for param in leading[len(args_list) :]:
            if param.name in kwargs_copy and param.kind is not inspect.Parameter.POSITIONAL_ONLY:
                args_list.append(kwargs_copy.pop(param.name))
            elif param.default is not inspect.Parameter.empty and param.default is not MISSING:
                args_list.append(param.default)
            else:
                raise TypeError(f"cannot replace *args: parameter {param.name!r} was not passed")
        args_list = args_list[: len(leading)] + list(new_var_args)
    return tuple(args_list), kwargs_copy


def replace_raw_args(
    sig: inspect.Signature | None,
    raw_args: tuple[Any, ...],
    raw_kwargs: dict[str, Any],
    updates: dict[str, Any],
) -> tuple[tuple[Any, ...], dict[str, Any]]:
    """Return ``(raw_args, raw_kwargs)`` with parameter values in ``updates`` replaced.

    Parameters already passed positionally in ``raw_args`` are replaced in place;
    omitted positional-only parameters are appended to ``raw_args`` (filling any
    preceding positional-only parameters from their defaults);
    other known parameters (or any key when ``sig`` has ``**kwargs``) are set in
    ``raw_kwargs``. The reserved key ``"var_args"`` (or the name of the
    ``*args`` parameter) replaces the values collected by ``*args``: the new
    sequence is spliced into ``raw_args`` after the preceding positional
    parameters, which are moved out of ``raw_kwargs`` (or filled with their
    defaults) if they were passed by keyword.

    If ``updates`` cannot be applied to ``sig``, logs a rate-limited warning and
    returns ``(raw_args, raw_kwargs)`` unchanged.
    """
    try:
        return _replace_raw_args(sig, raw_args, raw_kwargs, updates)
    except (KeyError, TypeError):
        log_bind_failure("<unknown>", "replace_raw_args")
        return tuple(raw_args), dict(raw_kwargs)


_replace_raw_args_public = replace_raw_args


@functools.cache
def _installed_version(library: str) -> str | None:
    try:
        return version(library)
    except PackageNotFoundError:
        return None


def _installed_signature(original: Any) -> inspect.Signature | None:
    try:
        target: Any = original.__func__ if type(original) in (classmethod, staticmethod) else original
        return inspect.signature(target)
    except Exception:  # pylint: disable=broad-exception-caught
        return None


_P = TypeVar("_P", PatchDef, InstancePatchDef)


def _below_locked_floor(
    library: str,
    subject: str,
    installed: str | None,
    locked_versions: frozenset[str],
) -> bool:
    """Whether ``installed`` is below the lowest locked version."""
    if installed is None or not locked_versions:
        return False
    try:
        target = Version(installed)
        floor_str = min(locked_versions, key=Version)
        floor = Version(floor_str)
    except InvalidVersion:
        return False
    if target < floor:
        log_signature_mismatch(
            library,
            f"{subject} {installed} is below the minimum locked version {floor_str}; skipping instrumentation",
        )
        return True
    return False


def _version_in_locked_range(installed: str, locked_versions: frozenset[str]) -> bool:
    """Whether ``installed`` falls between the oldest and newest locked versions."""
    if not locked_versions:
        return False
    try:
        target = Version(installed)
        parsed = [Version(v) for v in locked_versions]
    except InvalidVersion:
        return False
    return min(parsed) <= target <= max(parsed)


def _in_range(library: str, installed: str | None, patches: Sequence[_P]) -> list[_P]:
    """Patches whose ``versions`` range admits the installed version.

    If the installed version cannot be determined, patches with a range are
    skipped (one of several alternatives for the same target would otherwise
    be ambiguous) and an error is logged.
    """
    selected: list[_P] = []
    parsed: Version | None = None
    if installed is not None:
        try:
            parsed = Version(installed)
        except InvalidVersion:
            parsed = None
    for patch in patches:
        if patch.versions is None:
            selected.append(patch)
        elif parsed is None:
            _logger.error("%s: installed version unknown; skipping version-specific patch %s", library, patch.name)
        elif SpecifierSet(patch.versions).contains(parsed, prereleases=True):
            selected.append(patch)
    return selected


def _shape_matches(shape: ParamShape, locked_shapes: frozenset[ParamShape]) -> bool:
    """Whether ``shape`` is locked; patches without locked shapes always match."""
    return not locked_shapes or shape in locked_shapes


def _check_lock(
    library: str,
    installed: str | None,
    locked_versions: frozenset[str],
    resolved: Sequence[tuple[PatchDef, object, str, Any, inspect.Signature]],
    *,
    subject: str | None = None,
) -> None:
    subject = subject or library
    mismatched = [
        (patch, sig) for patch, _, _, _, sig in resolved if not _shape_matches(_shape(sig), patch.locked_shapes)
    ]
    if installed is not None and installed not in locked_versions:
        # Every resolved signature matching a locked shape is evidence that the
        # unlocked version is compatible; patches without locked shapes give none.
        shapes_verified = not mismatched and all(patch.locked_shapes for patch, _, _, _, _ in resolved)
        if shapes_verified or _version_in_locked_range(installed, locked_versions):
            _logger.debug(
                "%s: %s %s was not in the lock when this instrumentation was generated",
                library,
                subject,
                installed,
            )
        else:
            log_signature_mismatch(
                library,
                f"{subject} {installed} was not in the lock when this instrumentation was generated",
            )
    for patch, sig in mismatched:
        log_signature_mismatch(
            library,
            f"signature of {patch.target} differs from every locked version: {sig}",
        )


def _resolve_all(
    library: str,
    installed: str | None,
    patches: Sequence[PatchDef],
) -> list[tuple[PatchDef, object, str, Any, inspect.Signature]] | None:
    in_range = _in_range(library, installed, patches)
    if patches and not in_range:
        if installed is not None:
            log_signature_mismatch(
                library,
                f"no patches match installed version {installed}; skipping instrumentation",
            )
        return None
    resolved: list[tuple[PatchDef, object, str, Any, inspect.Signature]] = []
    for patch in in_range:
        found = _resolve(patch.target)
        if found is None:
            if patch.required:
                _report_error(library, f"patch target {patch.target} not found; nothing was patched")
                return None
            _logger.debug("%s: optional patch target %s not found; skipping", library, patch.target)
            continue
        owner, attr, original = found
        try:
            vars(owner)
        except TypeError:
            if patch.required:
                _report_error(
                    library,
                    f"cannot patch {patch.target}: owner does not support attribute assignment; nothing was patched",
                )
                return None
            _logger.debug(
                "%s: optional patch target %s owner does not support attribute assignment; skipping",
                library,
                patch.target,
            )
            continue
        sig = _installed_signature(original)
        if sig is None:
            _report_error(library, f"cannot read the signature of {patch.target}; nothing was patched")
            return None
        resolved.append((patch, owner, attr, original, sig))
    return resolved


def _make_class_detach(registry: Registry, entry: _Applied) -> Callable[[], None]:
    def detach() -> None:
        try:
            if _still_installed(entry):
                if entry.had_own:
                    setattr(entry.owner, entry.attr, entry.previous)
                else:
                    delattr(entry.owner, entry.attr)
        except Exception:  # pylint: disable=broad-exception-caught
            _logger.error(
                "%s: failed to self-remove patch on %r.%s",
                registry.library,
                entry.owner,
                entry.attr,
                exc_info=True,
            )
        try:
            registry._applied.remove(entry)  # pylint: disable=protected-access
        except ValueError:
            pass

    return detach


def _make_instance_detach(library: str, obj: object, attr: str, installed: Any) -> Callable[[], None]:
    def detach() -> None:
        try:
            if hasattr(obj, "__dict__") and vars(obj).get(attr) is installed:
                delattr(obj, attr)
        except Exception:  # pylint: disable=broad-exception-caught
            _logger.error("%s: failed to self-remove instance patch on %r.%s", library, obj, attr, exc_info=True)

    return detach


def apply_all(
    registry: Registry,
    *,
    locked_versions: frozenset[str],
    patches: Sequence[PatchDef],
    extra: Sequence[Manual] = (),
) -> bool:
    """Apply all class-scope patches as a unit.

    1. Resolve every target. A missing required target logs an error and
       nothing is patched.
    2. Compare the installed version and signatures with the lock and warn
       (or raise in strict mode) on mismatch.
    3. Apply every patch, then every :class:`Manual`. If anything fails, the
       patches already applied are unwound, the error is logged, and ``False``
       is returned.

    Returns whether patches were applied.
    """
    if registry.active:
        _logger.warning("%s: patches are already applied", registry.library)
        return False
    # Entries whose wrappers were all replaced by someone else are stale.
    registry._applied.clear()  # pylint: disable=protected-access

    installed = registry.installed_version()
    if _below_locked_floor(registry.library, registry.subject, installed, locked_versions):
        return False
    resolved = _resolve_all(registry.library, installed, patches)
    if resolved is None:
        return False

    _check_lock(registry.library, installed, locked_versions, resolved, subject=registry.subject)

    try:
        for patch, owner, attr, original, sig in resolved:
            own: dict[str, Any] = vars(owner)
            entry = _Applied(owner=owner, attr=attr, had_own=attr in own, previous=own.get(attr))
            raw_wrapper = patch.make_wrapper(_drop_first(sig) if patch.method else sig)
            installed_wrapper = _FunctionWrapper(original, raw_wrapper)
            setattr(owner, attr, installed_wrapper)
            entry.installed = installed_wrapper
            set_detach = getattr(raw_wrapper, "_set_detach", None)
            if set_detach is not None:
                set_detach(_make_class_detach(registry, entry))
            registry._applied.append(entry)  # pylint: disable=protected-access
        for manual in extra:
            manual.apply()
            registry._applied.append(_Applied(manual=manual))  # pylint: disable=protected-access
    except Exception:  # pylint: disable=broad-exception-caught
        _logger.error("%s: failed to apply patches; unwinding", registry.library, exc_info=True)
        unwind(registry)
        return False
    except BaseException:
        unwind(registry)
        raise
    return True


def unwind(registry: Registry) -> None:
    """Remove everything recorded in ``registry`` in reverse order.

    An attribute that no longer holds the wrapper we installed (someone else,
    e.g. ``mock.patch``, replaced it) is left alone.
    """
    applied = registry._applied  # pylint: disable=protected-access
    while applied:
        entry = applied.pop()
        try:
            if entry.manual is not None:
                entry.manual.remove()
            elif not _still_installed(entry):
                _logger.debug(
                    "%s: %r.%s was replaced after instrumentation; leaving it alone",
                    registry.library,
                    entry.owner,
                    entry.attr,
                )
            elif entry.had_own:
                setattr(entry.owner, entry.attr, entry.previous)
            else:
                delattr(entry.owner, entry.attr)
        except Exception:  # pylint: disable=broad-exception-caught
            _logger.error(
                "%s: failed to unwind patch on %r.%s",
                registry.library,
                entry.owner,
                entry.attr,
                exc_info=True,
            )


def apply_instance(
    obj: object,
    patches: Sequence[InstancePatchDef],
    *,
    class_registry: Registry,
    locked_versions: frozenset[str] = frozenset(),
) -> bool:
    """Shadow methods on a single object with wrappers, as a unit.

    * Objects without a ``__dict__`` (``__slots__``, some extension types) log
      an error and are left alone.
    * If the object's class is already patched through ``class_registry``,
      that patch is skipped so the wrapper runs once.
    * Instrumenting the same object twice warns and is a no-op.

    Returns whether any wrapper was installed.
    """
    library = class_registry.library
    if not hasattr(obj, "__dict__"):
        _logger.error("%s: cannot instrument %r: object does not support attribute assignment", library, obj)
        return False
    own = vars(obj)
    if any(isinstance(own.get(patch.attr), _InstancePatch) for patch in patches):
        _logger.warning("%s: %r is already instrumented", library, obj)
        return False

    installed = class_registry.installed_version()
    if _below_locked_floor(library, class_registry.subject, installed, locked_versions):
        return False
    in_range = _in_range(library, installed, patches)
    if patches and not in_range:
        if installed is not None:
            log_signature_mismatch(
                library,
                f"no patches match installed version {installed}; skipping instrumentation",
            )
        return False

    applied: list[str] = []
    removed_opt_outs: list[tuple[str, Any]] = []

    def unwind_instance() -> None:
        for attr in reversed(applied):
            try:
                delattr(obj, attr)
            except Exception:  # pylint: disable=broad-exception-caught
                _logger.error("%s: failed to unwind %r.%s", library, obj, attr, exc_info=True)
        for attr, opt_out in reversed(removed_opt_outs):
            try:
                setattr(obj, attr, opt_out)
            except Exception:  # pylint: disable=broad-exception-caught
                _logger.error("%s: failed to restore opt-out on %r.%s", library, obj, attr, exc_info=True)

    try:
        for patch in in_range:
            existing_opt_out = own.get(patch.attr)
            if isinstance(existing_opt_out, _InstanceOptOut):
                delattr(obj, patch.attr)
                removed_opt_outs.append((patch.attr, existing_opt_out))
            if class_registry.owns(inspect.getattr_static(type(obj), patch.attr, None)) or any(
                class_registry.owns(vars(cls).get(patch.attr)) for cls in type(obj).__mro__ if hasattr(cls, "__dict__")
            ):
                continue
            bound = getattr(obj, patch.attr, None)
            if bound is None:
                continue
            try:
                sig = inspect.signature(bound)
            except Exception:  # pylint: disable=broad-exception-caught
                _logger.error("%s: cannot read the signature of %r.%s", library, obj, patch.attr)
                continue
            instance_shapes = frozenset(shape[1:] for shape in patch.locked_shapes)
            if not _shape_matches(_shape(sig), instance_shapes):
                log_signature_mismatch(
                    library,
                    f"signature of {type(obj).__qualname__}.{patch.attr} differs from every locked version: {sig}",
                )
            raw_wrapper = patch.make_wrapper(sig)
            installed_wrapper = _InstancePatch(bound, raw_wrapper)
            try:
                setattr(obj, patch.attr, installed_wrapper)
            except (AttributeError, TypeError):
                _logger.error("%s: cannot instrument %r: attribute assignment rejected", library, obj)
                unwind_instance()
                return False
            set_detach = getattr(raw_wrapper, "_set_detach", None)
            if set_detach is not None:
                set_detach(_make_instance_detach(library, obj, patch.attr, installed_wrapper))
            applied.append(patch.attr)
    except PatchMismatchError:
        unwind_instance()
        raise
    except Exception:  # pylint: disable=broad-exception-caught
        _logger.error("%s: failed to instrument %r; unwinding", library, obj, exc_info=True)
        unwind_instance()
        return False
    except BaseException:
        unwind_instance()
        raise
    return bool(applied)


def remove_instance(obj: object, attrs: Sequence[str], *, class_registry: Registry) -> None:
    """Undo :func:`apply_instance` for ``obj``.

    Instance wrappers are deleted, which unshadows the class attribute. If the
    class itself is currently patched through ``class_registry``, the object
    is additionally pinned to the original method so that it stays
    uninstrumented, matching what ``uninstrument_client``-style APIs promise.
    """
    if not hasattr(obj, "__dict__"):
        return
    own = vars(obj)
    for attr in attrs:
        current = own.get(attr)
        if isinstance(current, (_InstancePatch, _InstanceOptOut)):
            delattr(obj, attr)
        static = inspect.getattr_static(type(obj), attr, None)
        if class_registry.owns(static):
            original = static.__wrapped__
            bound = original.__get__(obj, type(obj))  # pylint: disable=unnecessary-dunder-call
            setattr(obj, attr, _InstanceOptOut(bound, _passthrough))
